function [ys_, params, info] = steadystate(ys_, exo_, params)
% Steady state generated by Dynare preprocessor
    info = 0;
    ys_(1)=params(1);
    ys_(7)=params(12);
    mu_ss=1+params(4);
    epsi_ss=(1+params(4))/params(4);
    b_ss=params(1)*params(9);
    ys_(9)=ys_(7)^(1/(epsi_ss-1));
    ys_(8)=ys_(7)*params(3)/(1-params(3));
    rho_ss=(1-params(2))/params(2);
    ys_(5)=params(7)/(1-params(3));
    ys_(6)=params(8)/(1-params(3));
    ys_(4)=ys_(5)/ys_(6);
    ys_(3)=params(6)/(params(6)+(1-params(3))*ys_(5));
    ys_(17)=1-ys_(3);
    ys_(2)=ys_(4)*ys_(3);
    recruiter_share_ss=(params(3)+(epsi_ss-1)*(params(3)+rho_ss))/(params(3)+epsi_ss*(params(3)+rho_ss));
    w_wR_ss=params(11)/recruiter_share_ss;
    ys_(10)=ys_(1)/w_wR_ss;
    z_ss=ys_(10)*mu_ss/ys_(9);
    f_e_ss=(1-params(3))*z_ss*(mu_ss-1)*ys_(17)/ys_(7)/(rho_ss+mu_ss*params(3));
    ys_(11)=ys_(9)*f_e_ss/mu_ss;
    ys_(12)=ys_(11)*(params(3)+rho_ss)/(1-params(3));
    ys_(18)=ys_(8)*f_e_ss/z_ss;
    ys_(19)=ys_(17)-ys_(18);
    ys_(13)=ys_(19)*ys_(9)*z_ss;
    gam_ss=(1-params(3))*ys_(6)/(rho_ss+params(6))*(ys_(10)-ys_(1));
    ys_(14)=ys_(13)-ys_(2)*gam_ss;
    ys_(15)=ys_(14)^(-params(5));
    ys_(16)=ys_(13)+ys_(8)*ys_(11);
    ys_(20)=params(11);
    ys_(21)=0;
    ys_(23)=0;
    ys_(22)=0;
    ys_(24)=0;
    ys_(25)=0;
    z_imp=0;
    ys_(26)=100*log(ys_(3));
    ys_(27)=100*log(ys_(2));
    ys_(28)=100*log(ys_(4));
    ys_(29)=100*log(ys_(7));
    ys_(30)=100*log(ys_(8));
    ys_(31)=100*log(ys_(14));
    % Auxiliary equations
ys_(32)=ys_(22);
end
